from collections import deque
def component_map(H,W,pts):
 rem=set(pts); ids={};i=0
 while rem:
  p=rem.pop();q=[p]; ids[p]=i
  while q:
   r,c=q.pop()
   for n in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
